def solve(grid):
    rows = len(grid)
    cols = len(grid[0])

    from collections import defaultdict
    positions = defaultdict(list)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                positions[grid[r][c]].append((r, c))

    all_nz = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] != 0]
    avg_r = sum(r for r, c in all_nz) / len(all_nz)
    avg_c = sum(c for r, c in all_nz) / len(all_nz)

    candidates = []
    for r, c in all_nz:
        v = grid[r][c]
        if len(positions[v]) >= 2:
            d = (r - avg_r)**2 + (c - avg_c)**2
            candidates.append((d, r, c))
    candidates.sort()
    center_r, center_c = candidates[0][1], candidates[0][2]
    center_val = grid[center_r][center_c]

    ext_pos = max(positions[center_val], key=lambda p: abs(p[0]-center_r)+abs(p[1]-center_c))
    er, ec = ext_pos
    dr, dc = er - center_r, ec - center_c
    if abs(dr) >= abs(dc):
        ext_dir = 0 if dr < 0 else 2
    else:
        ext_dir = 1 if dc > 0 else 3

    dirs = [(-1,0),(0,1),(1,0),(0,-1)]
    ring_info = []

    for d in range(1, max(rows, cols)):
        vals = {}
        any_valid = False
        for d_idx in range(4):
            ddr, ddc = dirs[d_idx]
            r, c = center_r + ddr*d, center_c + ddc*d
            if 0 <= r < rows and 0 <= c < cols:
                vals[d_idx] = grid[r][c]
                any_valid = True
            else:
                vals[d_idx] = -1
        if not any_valid:
            break
        non_zero = {d_idx: v for d_idx, v in vals.items() if v > 0}
        if len(non_zero) >= 3:
            ring_val = list(non_zero.values())[0]
            gap_dir = None
            for d_idx in range(4):
                if vals.get(d_idx, -1) == 0:
                    gap_dir = d_idx
            if gap_dir is not None:
                ring_info.append((ring_val, gap_dir))

    output = []
    for ring_val, gap_dir in ring_info:
        count = (ext_dir - gap_dir) % 4
        row = [ring_val]*count + [0]*(3-count)
        output.append(row)

    return output

